// LikeGroupBy groups the rows of a `LikeQuery`. Start one with `group_by`.
pub struct LikeGroupBy {
	query LikeQuery
pub:
	columns    []string
	aggregates []load.Aggregate
}

// group_by groups the matching rows by `columns`. It needs a vgraph driver.
pub fn (q LikeQuery) group_by(columns ...string) LikeGroupBy {
	return LikeGroupBy{
		query:   q
		columns: columns
	}
}

// aggregate adds what each group gets, such as `vgraph.count()` or
// `vgraph.sum('views')`.
pub fn (g LikeGroupBy) aggregate(aggregates ...load.Aggregate) LikeGroupBy {
	mut all := g.aggregates.clone()
	all << aggregates
	return LikeGroupBy{
		...g
		aggregates: all
	}
}

// all returns the groups, ordered by their columns.
pub fn (g LikeGroupBy) all() ![]load.Group {
	q := g.query
	return load.group_where(q.graph.client.conn, 'likes', q.graph.client.prepare_query('likes', q.query)!, g.columns.map(load.GroupColumn{
		name: it
		typ:  like_column_type(it)
	}), g.aggregates)
}

// scan reads the groups into `T`, by name: its fields named after the grouped
// columns and the aggregates (`count`, `sum_views`).
pub fn (g LikeGroupBy) scan[T]() ![]T {
	return load.scan_groups[T](g.all()!)
}

// like_column_type returns the V type of a column of `likes`.
fn like_column_type(column string) string {
	return match column {
		'id' { 'int' }
		'user_id' { 'int' }
		'gadget_id' { 'i64' }
		'liked_at' { 'time.Time' }
		else { '' }
	}
}

// order_by_user_name orders the rows by the `name` of their `user`.
pub fn (q LikeQuery) order_by_user_name() LikeQuery {
	return q.order_by(load.Order{
		expr: '(SELECT "t1"."name" FROM "users" AS "t1" WHERE "t1"."id" = "t0"."user_id")'
	})
}

