// with_user loads each row's `user` (many_to_one `users`) with it, in one
// query for all the rows. `configure` narrows them, and can load their edges.
pub fn (q LikeQuery) with_user(configure ...fn (UserQuery) UserQuery) LikeQuery {
	mut next := q
	next.with_user = true
	next.user_fns = configure
	return next
}

// with_gadget loads each row's `gadget` (many_to_one `gadgets`) with it, in one
// query for all the rows. `configure` narrows them, and can load their edges.
pub fn (q LikeQuery) with_gadget(configure ...fn (GadgetQuery) GadgetQuery) LikeQuery {
	mut next := q
	next.with_gadget = true
	next.gadget_fns = configure
	return next
}

// all returns the matching rows, with the requested edges.
pub fn (q LikeQuery) all() ![]LikeNode {
	rows := load.select_where[models.Like](q.graph.client.conn, q.graph.client.prepare_query('likes', q.query)!)!
	return q.nodes(rows)
}

// first returns the first matching row, with the requested edges, or a
// `NotFoundError`.
pub fn (q LikeQuery) first() !LikeNode {
	nodes := q.limit(1).all()!
	if nodes.len == 0 {
		return NotFoundError{
			table: 'likes'
		}
	}
	return nodes[0]
}

// nodes loads the requested edges onto `rows`, which the caller already has: one
// query per edge, however many rows there are.
pub fn (q LikeQuery) nodes(rows []models.Like) ![]LikeNode {
	mut nodes := rows.map(LikeNode{
		graph: q.graph
		like:  it
	})
	if q.with_user {
		found := q.load_user(rows, q.user_fns)!
		for mut node in nodes {
			// at most one each: the first, in the order of the query
			list := found[node.like.id.str()] or { [] }
			if list.len > 0 {
				node.user = &UserNode{
					...list[0]
				}
			}
			node.loaded << 'user'
		}
	}
	if q.with_gadget {
		found := q.load_gadget(rows, q.gadget_fns)!
		for mut node in nodes {
			// at most one each: the first, in the order of the query
			list := found[node.like.id.str()] or { [] }
			if list.len > 0 {
				node.gadget = &GadgetNode{
					...list[0]
				}
			}
			node.loaded << 'gadget'
		}
	}
	return nodes
}

// load_user loads the `user` of `rows`, keyed by each row's key.
fn (q LikeQuery) load_user(rows []models.Like, fns []fn (UserQuery) UserQuery) !map[string][]UserNode {
	mut sub := q.graph.users()
	for configure in fns {
		sub = configure(sub)
	}
	mut keys := []string{}
	for row in rows {
		keys << row.user_id.str()
	}
	targets := sub.nodes(load.select_in[models.User](q.graph.client.conn, 'id', load.unique(keys),
		query: q.graph.client.prepare_query('users', sub.query)!
	)!)!
	mut by_key := map[string]UserNode{}
	for target in targets {
		by_key[target.user.id.str()] = target
	}
	mut found := map[string][]UserNode{}
	for row in rows {
		if target := by_key[row.user_id.str()] {
			found[row.id.str()] = [target]
		}
	}
	return found
}

// user_or_err returns the `user`: a `NotLoadedError` when the query didn't
// load it, a `NotFoundError` when the row has none.
pub fn (n LikeNode) user_or_err() !&UserNode {
	if 'user' !in n.loaded {
		return NotLoadedError{
			edge: 'likes.user'
		}
	}
	if target := n.user {
		return target
	}
	return NotFoundError{
		table: 'users'
	}
}

// load_gadget loads the `gadget` of `rows`, keyed by each row's key.
fn (q LikeQuery) load_gadget(rows []models.Like, fns []fn (GadgetQuery) GadgetQuery) !map[string][]GadgetNode {
	mut sub := q.graph.gadgets()
	for configure in fns {
		sub = configure(sub)
	}
	mut keys := []string{}
	for row in rows {
		keys << row.gadget_id.str()
	}
	targets := sub.nodes(load.select_in[models.Gadget](q.graph.client.conn, 'id', load.unique(keys),
		query: q.graph.client.prepare_query('gadgets', sub.query)!
	)!)!
	mut by_key := map[string]GadgetNode{}
	for target in targets {
		by_key[target.gadget.id.str()] = target
	}
	mut found := map[string][]GadgetNode{}
	for row in rows {
		if target := by_key[row.gadget_id.str()] {
			found[row.id.str()] = [target]
		}
	}
	return found
}

// gadget_or_err returns the `gadget`: a `NotLoadedError` when the query didn't
// load it, a `NotFoundError` when the row has none.
pub fn (n LikeNode) gadget_or_err() !&GadgetNode {
	if 'gadget' !in n.loaded {
		return NotLoadedError{
			edge: 'likes.gadget'
		}
	}
	if target := n.gadget {
		return target
	}
	return NotFoundError{
		table: 'gadgets'
	}
}

// query_user starts a query of this row's `user`, which matches
// nothing when the row has none.
pub fn (n LikeNode) query_user() UserQuery {
	key := n.like.user_id
	return n.graph.users().where(load.eq('id', key))
}

// query_gadget starts a query of this row's `gadget`, which matches
// nothing when the row has none.
pub fn (n LikeNode) query_gadget() GadgetQuery {
	key := n.like.gadget_id
	return n.graph.gadgets().where(load.eq('id', key))
}
